INSERT INTO `sales_bid_chapter` VALUES (297, 1, NULL, '二、 服务内容与技术要求', '一级目录', NULL, '本模块详细描述了日喀则市公安局清标平台建设项目的服务内容与技术要求，包括系统功能清单、技术指标、交付时间、培训要求及售后服务等关键内容。', NULL, 0, NULL, 1, NULL);
INSERT INTO `sales_bid_chapter` VALUES (298, 1, NULL, '三、 投标要求', '一级目录', NULL, '本模块详细规定了投标人的资格要求、响应文件的编制与递交、磋商及评审流程、合同的签订与履行等内容，确保采购过程的合规性和透明度。', NULL, 0, NULL, 2, NULL);
INSERT INTO `sales_bid_chapter` VALUES (299, 1, NULL, '四、 商务条款与合同', '一级目录', NULL, NULL, NULL, 0, NULL, 3, NULL);
INSERT INTO `sales_bid_chapter` VALUES (300, 1, NULL, '五、 评标标准与方法', '一级目录', NULL, '本模块详细规定了评标标准与方法，包括评分细则、商务和技术审查、价格评审等内容，确保评标过程公平、公正。', NULL, 0, NULL, 4, NULL);
INSERT INTO `sales_bid_chapter` VALUES (301, 1, NULL, '六、 风险与合规', '一级目录', NULL, '本模块主要涉及响应人在招投标过程中的风险控制与合规要求，包括资格审查不通过情形、违约责任、服务中断及质量不达标的处罚等关键条款。', NULL, 0, NULL, 5, NULL);
INSERT INTO `sales_bid_chapter` VALUES (302, 1, 296, '1.1项目名称', '二级目录', '项目名称：日喀则市公安局清标平台建设项目', '明确了项目的名称为日喀则市公安局清标平台建设项目。', 'low', 0, NULL, 0, '[{\"Label\":\"\\u9879\\u76EE\\u540D\\u79F0\",\"Value\":\"\\u65E5\\u5580\\u5219\\u5E02\\u516C\\u5B89\\u5C40\\u6E05\\u6807\\u5E73\\u53F0\\u5EFA\\u8BBE\\u9879\\u76EE\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (303, 1, 296, '1.2项目编号', '二级目录', '项目编号：XZRM-RKZCG-2025090', '提供了项目的唯一编号。', 'low', 0, NULL, 1, '[{\"Label\":\"\\u9879\\u76EE\\u7F16\\u53F7\",\"Value\":\"XZRM-RKZCG-2025090\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (304, 1, 296, '1.3项目内容及预算', '二级目录', '预算金额：65万元（陆拾伍万元整）\n最高限价：65万元（陆拾伍万元整）\n采购需求：平台建设（具体内容及要求详见竞争性磋商文件采购清单表）', '详细说明了项目的内容和预算金额。', 'medium', 0, NULL, 2, '[{\"Label\":\"\\u9884\\u7B97\\u91D1\\u989D\",\"Value\":\"65\\u4E07\\u5143\",\"FullWidth\":false},{\"Label\":\"\\u6700\\u9AD8\\u9650\\u4EF7\",\"Value\":\"65\\u4E07\\u5143\",\"FullWidth\":false},{\"Label\":\"\\u91C7\\u8D2D\\u9700\\u6C42\",\"Value\":\"\\u5E73\\u53F0\\u5EFA\\u8BBE\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (305, 1, 296, '1.4合同履行期限', '二级目录', '合同履行期限：30个日历天内完成系统部署、测试和初步培训', '规定了项目完成的时间要求。', 'medium', 0, NULL, 3, '[{\"Label\":\"\\u5408\\u540C\\u5C65\\u884C\\u671F\\u9650\",\"Value\":\"30\\u4E2A\\u65E5\\u5386\\u5929\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (306, 1, 296, '2.1响应人资格条件', '二级目录', '2.1应具备《中华人民共和国政府采购法》第二十二条规定的条件；\n2.2本项目不接受/接受联合体响应，不允许转包。', '列出了响应人需要满足的基本资格条件。', 'high', 1, NULL, 4, '[{\"Label\":\"\\u8D44\\u683C\\u6761\\u4EF6\",\"Value\":\"\\u300A\\u4E2D\\u534E\\u4EBA\\u6C11\\u5171\\u548C\\u56FD\\u653F\\u5E9C\\u91C7\\u8D2D\\u6CD5\\u300B\\u7B2C\\u4E8C\\u5341\\u4E8C\\u6761\",\"FullWidth\":false},{\"Label\":\"\\u8054\\u5408\\u4F53\\u54CD\\u5E94\",\"Value\":\"\\u4E0D\\u63A5\\u53D7/\\u63A5\\u53D7\",\"FullWidth\":false},{\"Label\":\"\\u8F6C\\u5305\",\"Value\":\"\\u4E0D\\u5141\\u8BB8\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (307, 1, 296, '3.1采购文件获取方式', '二级目录', '采购文件获取方式：线下获取；\n采购文件获取期限：2025年10月11日至2025年10月16日；\n采购文件获取方式：西藏瑞铭项目管理有限公司（日喀则市达热瓦小区二期A区6栋13号）\n采购文件获取费用：500元/份', '说明了获取采购文件的途径和要求。', 'low', 0, NULL, 5, '[{\"Label\":\"\\u83B7\\u53D6\\u65B9\\u5F0F\",\"Value\":\"\\u7EBF\\u4E0B\\u83B7\\u53D6\",\"FullWidth\":false},{\"Label\":\"\\u83B7\\u53D6\\u671F\\u9650\",\"Value\":\"2025\\u5E7410\\u670811\\u65E5\\u81F32025\\u5E7410\\u670816\\u65E5\",\"FullWidth\":false},{\"Label\":\"\\u83B7\\u53D6\\u5730\\u70B9\",\"Value\":\"\\u897F\\u85CF\\u745E\\u94ED\\u9879\\u76EE\\u7BA1\\u7406\\u6709\\u9650\\u516C\\u53F8\\uFF08\\u65E5\\u5580\\u5219\\u5E02\\u8FBE\\u70ED\\u74E6\\u5C0F\\u533A\\u4E8C\\u671FA\\u533A6\\u680B13\\u53F7\\uFF09\",\"FullWidth\":false},{\"Label\":\"\\u83B7\\u53D6\\u8D39\\u7528\",\"Value\":\"500\\u5143/\\u4EFD\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (308, 1, 296, '4.1响应时间', '二级目录', '响应时间：2025年10月21日 15:00至15:30（北京时间）；\n磋商时间（响应截止时间）：2025年10月21日15:30（北京时间）；\n磋商地点：日喀则市公安局', '规定了响应文件的提交时间和地点。', 'high', 1, NULL, 6, '[{\"Label\":\"\\u54CD\\u5E94\\u65F6\\u95F4\",\"Value\":\"2025\\u5E7410\\u670821\\u65E5 15:00\\u81F315:30\",\"FullWidth\":false},{\"Label\":\"\\u78CB\\u5546\\u65F6\\u95F4\",\"Value\":\"2025\\u5E7410\\u670821\\u65E515:30\",\"FullWidth\":false},{\"Label\":\"\\u78CB\\u5546\\u5730\\u70B9\",\"Value\":\"\\u65E5\\u5580\\u5219\\u5E02\\u516C\\u5B89\\u5C40\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (309, 1, 297, '采购标的', '二级目录', '本项目采购一套政府采购投标文件智能审查软件系统（以下简称“系统”），用于辅助采购人开展政府采购项目投标文件审查工作。该系统应基于大数据分析和算法技术，实现对投标文件内容的自动化比对、异常预警和报告生成，支持采购人识别潜在围标串标风险，提高审查效率和准确性。系统应符合《中华人民共和国政府采购法》及相关实施条例的要求，确保审查过程合规、透明、安全。', '概述了系统的主要功能和用途，强调合规性和自动化审查能力。', 'medium', 0, NULL, 0, '[{\"Label\":\"\\u7CFB\\u7EDF\\u7528\\u9014\",\"Value\":\"\\u653F\\u5E9C\\u91C7\\u8D2D\\u6295\\u6807\\u6587\\u4EF6\\u667A\\u80FD\\u5BA1\\u67E5\",\"FullWidth\":false},{\"Label\":\"\\u6838\\u5FC3\\u6280\\u672F\",\"Value\":\"\\u5927\\u6570\\u636E\\u5206\\u6790\\u548C\\u7B97\\u6CD5\\u6280\\u672F\",\"FullWidth\":false},{\"Label\":\"\\u5408\\u89C4\\u8981\\u6C42\",\"Value\":\"\\u7B26\\u5408\\u300A\\u4E2D\\u534E\\u4EBA\\u6C11\\u5171\\u548C\\u56FD\\u653F\\u5E9C\\u91C7\\u8D2D\\u6CD5\\u300B\\u53CA\\u76F8\\u5173\\u5B9E\\u65BD\\u6761\\u4F8B\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (310, 1, 297, '功能要求', '二级目录', '系统应具备以下核心功能模块，支持采购人高效开展投标文件审查工作。功能设计应以采购人业务需求为导向，确保操作简便、界面友好，并支持多用户权限管理。每个模块下应细化子功能，以覆盖政府采购审查全流程，包括文件处理、风险识别、分析比对、结果输出和辅助管理。系统应支持自定义配置规则，确保灵活适应不同项目规模和审查场景。', '详细列出了系统的核心功能模块，包括文件上传、异常预警、内容比对和报告生成等。', 'high', 0, NULL, 1, '[{\"Label\":\"\\u6838\\u5FC3\\u529F\\u80FD\\u6A21\\u5757\",\"Value\":\"\\u6587\\u4EF6\\u4E0A\\u4F20\\u4E0E\\u9879\\u76EE\\u7BA1\\u7406\\u3001\\u5F02\\u5E38\\u9884\\u8B66\\u3001\\u5185\\u5BB9\\u6BD4\\u5BF9\\u3001\\u62A5\\u544A\\u751F\\u6210\",\"FullWidth\":false},{\"Label\":\"\\u529F\\u80FD\\u8BBE\\u8BA1\\u539F\\u5219\",\"Value\":\"\\u64CD\\u4F5C\\u7B80\\u4FBF\\u3001\\u754C\\u9762\\u53CB\\u597D\\u3001\\u591A\\u7528\\u6237\\u6743\\u9650\\u7BA1\\u7406\",\"FullWidth\":false},{\"Label\":\"\\u81EA\\u5B9A\\u4E49\\u914D\\u7F6E\",\"Value\":\"\\u652F\\u6301\\u81EA\\u5B9A\\u4E49\\u914D\\u7F6E\\u89C4\\u5219\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (311, 1, 297, '性能要求', '二级目录', '系统响应时间：文件上传提交后，5家以内供应商投标文件分析处理时长不超过10分钟，5家以上供应商大规模比对不超过15分钟。准确率：内容相似度检测准确率不低于95%，异常预警召回率不低于90%。兼容性：支持文件格式Word；，统容量支持单项目文件总量不低于500MB。稳定性：系统可用率不低于99.5%，支持负载均衡，确保高峰期无中断。安全性：符合《网络安全法》要求，支持数据脱敏、备份恢复和涉密环境部署。', '规定了系统的响应时间、准确率、兼容性、稳定性和安全性等性能指标。', 'high', 0, NULL, 2, '[{\"Label\":\"\\u54CD\\u5E94\\u65F6\\u95F4\",\"Value\":\"5\\u5BB6\\u4EE5\\u518510\\u5206\\u949F\\uFF0C5\\u5BB6\\u4EE5\\u4E0A15\\u5206\\u949F\",\"FullWidth\":false},{\"Label\":\"\\u51C6\\u786E\\u7387\",\"Value\":\"\\u76F8\\u4F3C\\u5EA6\\u68C0\\u6D4B\\u226595%\\uFF0C\\u9884\\u8B66\\u53EC\\u56DE\\u7387\\u226590%\",\"FullWidth\":false},{\"Label\":\"\\u517C\\u5BB9\\u6027\",\"Value\":\"\\u652F\\u6301Word\\uFF0C\\u5355\\u9879\\u76EE\\u6587\\u4EF6\\u2265500MB\",\"FullWidth\":false},{\"Label\":\"\\u7A33\\u5B9A\\u6027\",\"Value\":\"\\u53EF\\u7528\\u7387\\u226599.5%\",\"FullWidth\":false},{\"Label\":\"\\u5B89\\u5168\\u6027\",\"Value\":\"\\u7B26\\u5408\\u300A\\u7F51\\u7EDC\\u5B89\\u5168\\u6CD5\\u300B\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (312, 1, 297, '交付要求', '二级目录', '交付时间：自采购人提供服务器或私有云部署环境后，30个日历天内完成系统部署、测试和初步培训。交付地点：采购人指定地点（以合同约定为准），支持本地化部署，包括软件安装、环境配置和数据迁移。部署方式：采用本地化部署模式，支持采购人服务器或私有云环境。供应商应提供部署方案，确保与采购人现有IT基础设施兼容。', '明确了系统的交付时间、地点和部署方式。', 'medium', 0, NULL, 3, '[{\"Label\":\"\\u4EA4\\u4ED8\\u65F6\\u95F4\",\"Value\":\"30\\u4E2A\\u65E5\\u5386\\u5929\",\"FullWidth\":false},{\"Label\":\"\\u90E8\\u7F72\\u65B9\\u5F0F\",\"Value\":\"\\u672C\\u5730\\u5316\\u90E8\\u7F72\",\"FullWidth\":false},{\"Label\":\"\\u517C\\u5BB9\\u6027\\u8981\\u6C42\",\"Value\":\"\\u4E0E\\u91C7\\u8D2D\\u4EBA\\u73B0\\u6709IT\\u57FA\\u7840\\u8BBE\\u65BD\\u517C\\u5BB9\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (313, 1, 297, '培训要求', '二级目录', '供应商应免费提供不少于3人天的系统操作培训，包括管理员培训（系统配置、管理）和用户培训（日常审查操作）。培训形式可结合现场和在线，支持培训资料提供（电子版手册）。培训后，采购人用户应能独立开展基本审查任务。', '规定了供应商需提供的培训内容和形式。', 'low', 0, NULL, 4, '[{\"Label\":\"\\u57F9\\u8BAD\\u65F6\\u957F\",\"Value\":\"\\u4E0D\\u5C11\\u4E8E3\\u4EBA\\u5929\",\"FullWidth\":false},{\"Label\":\"\\u57F9\\u8BAD\\u5F62\\u5F0F\",\"Value\":\"\\u73B0\\u573A\\u548C\\u5728\\u7EBF\\u7ED3\\u5408\",\"FullWidth\":false},{\"Label\":\"\\u57F9\\u8BAD\\u76EE\\u6807\",\"Value\":\"\\u72EC\\u7ACB\\u5F00\\u5C55\\u57FA\\u672C\\u5BA1\\u67E5\\u4EFB\\u52A1\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (314, 1, 297, '售后服务要求', '二级目录', '服务期限：软件正式验收合格后，提供不少于 1 年的免费质保期（含系统故障维修、缺陷修补、版本升级、技术咨询等服务）；质保期满后，供应商可提供延续维保服务（服务内容与质保期一致），维保费用由双方另行协商，且延续维保费用不高于原合同总金额的25%/年。​功能更新：支持最新的审核规则更新;每更新一个审核点收费为3万元;应急响应：若系统出现故障，提供不低于10个项目的人工支持。', '详细说明了售后服务的期限、内容及应急响应要求。', 'medium', 0, NULL, 5, '[{\"Label\":\"\\u8D28\\u4FDD\\u671F\",\"Value\":\"\\u4E0D\\u5C11\\u4E8E1\\u5E74\",\"FullWidth\":false},{\"Label\":\"\\u7EF4\\u4FDD\\u8D39\\u7528\\u4E0A\\u9650\",\"Value\":\"\\u4E0D\\u9AD8\\u4E8E\\u539F\\u5408\\u540C\\u603B\\u91D1\\u989D\\u768425%/\\u5E74\",\"FullWidth\":false},{\"Label\":\"\\u529F\\u80FD\\u66F4\\u65B0\\u8D39\\u7528\",\"Value\":\"\\u6BCF\\u66F4\\u65B0\\u4E00\\u4E2A\\u5BA1\\u6838\\u70B93\\u4E07\\u5143\",\"FullWidth\":false},{\"Label\":\"\\u5E94\\u6025\\u54CD\\u5E94\",\"Value\":\"\\u4E0D\\u4F4E\\u4E8E10\\u4E2A\\u9879\\u76EE\\u7684\\u4EBA\\u5DE5\\u652F\\u6301\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (315, 1, 298, '响应人资格条件', '二级目录', '1.3.1在中华人民共和国境内注册，能够独立承担民事责任，有生产或供应能力的本国供应商。1.3.2具备《中华人民共和国政府采购法》第二十二条关于供应商条件的规定，遵守政府采购的有关规定。', '规定了响应人必须满足的基本资格条件，包括注册、财务、法律合规等方面。', 'high', 1, NULL, 0, '[{\"Label\":\"\\u6CE8\\u518C\\u8981\\u6C42\",\"Value\":\"\\u4E2D\\u534E\\u4EBA\\u6C11\\u5171\\u548C\\u56FD\\u5883\\u5185\\u6CE8\\u518C\",\"FullWidth\":false},{\"Label\":\"\\u6CD5\\u5F8B\\u5408\\u89C4\",\"Value\":\"\\u9075\\u5B88\\u653F\\u5E9C\\u91C7\\u8D2D\\u6CD5\\u7B2C\\u4E8C\\u5341\\u4E8C\\u6761\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (316, 1, 298, '联合体响应规定', '二级目录', '1.4.1两个以上供应商可以组成一个响应联合体，以一个响应人的身份响应。1.4.2联合体各方均应符合《中华人民共和国政府采购法》第二十二条规定的条件。', '明确了联合体响应的具体要求和限制，包括联合体各方的资格和责任。', 'medium', 1, NULL, 1, '[{\"Label\":\"\\u8054\\u5408\\u4F53\\u7EC4\\u6210\",\"Value\":\"\\u4E24\\u4E2A\\u4EE5\\u4E0A\\u4F9B\\u5E94\\u5546\\u7EC4\\u6210\",\"FullWidth\":false},{\"Label\":\"\\u6CD5\\u5F8B\\u5408\\u89C4\",\"Value\":\"\\u7B26\\u5408\\u653F\\u5E9C\\u91C7\\u8D2D\\u6CD5\\u7B2C\\u4E8C\\u5341\\u4E8C\\u6761\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (317, 1, 298, '响应文件构成', '二级目录', '9.1 响应文件应按照采购文件第2章“响应文件格式”进行编写（可以增加附页），作为响应文件的组成部分。9.2上述文件应按照采购文件规定的格式填写、签署和盖章。', '详细列出了响应文件的组成部分及其具体要求，确保文件的完整性和规范性。', 'medium', 0, NULL, 2, '[{\"Label\":\"\\u6587\\u4EF6\\u683C\\u5F0F\",\"Value\":\"\\u6309\\u7167\\u7B2C2\\u7AE0\\u683C\\u5F0F\\u7F16\\u5199\",\"FullWidth\":false},{\"Label\":\"\\u7B7E\\u7F72\\u76D6\\u7AE0\",\"Value\":\"\\u6309\\u89C4\\u5B9A\\u683C\\u5F0F\\u586B\\u5199\\u3001\\u7B7E\\u7F72\\u548C\\u76D6\\u7AE0\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (318, 1, 298, '响应报价', '二级目录', '11.1所有响应均以人民币报价。响应人的响应报价应遵守《中华人民共和国价格法》。11.4响应人所报的各分项响应单价在合同履行过程中是固定不变的，不得以任何理由予以变更。', '规定了响应报价的具体要求和限制，包括报价方式、货币单位和价格调整。', 'high', 1, NULL, 3, '[{\"Label\":\"\\u8D27\\u5E01\\u5355\\u4F4D\",\"Value\":\"\\u4EBA\\u6C11\\u5E01\\u62A5\\u4EF7\",\"FullWidth\":false},{\"Label\":\"\\u4EF7\\u683C\\u56FA\\u5B9A\",\"Value\":\"\\u5206\\u9879\\u5355\\u4EF7\\u56FA\\u5B9A\\u4E0D\\u53D8\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (319, 1, 298, '响应文件递交', '二级目录', '16.1响应人应在响应人须知资料表中规定的截止时间前，提交响应文件。17.1在响应截止时间后提交的响应文件，采购代理机构和采购人将拒绝接受。', '明确了响应文件的递交方式、截止时间和修改撤回的规定。', 'high', 1, NULL, 4, '[{\"Label\":\"\\u622A\\u6B62\\u65F6\\u95F4\",\"Value\":\"\\u89C4\\u5B9A\\u622A\\u6B62\\u65F6\\u95F4\\u524D\\u63D0\\u4EA4\",\"FullWidth\":false},{\"Label\":\"\\u62D2\\u7EDD\\u63A5\\u53D7\",\"Value\":\"\\u622A\\u6B62\\u65F6\\u95F4\\u540E\\u63D0\\u4EA4\\u7684\\u6587\\u4EF6\\u62D2\\u7EDD\\u63A5\\u53D7\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (320, 1, 298, '磋商及评审', '二级目录', '20.1符合性审查是指依据采购文件的规定，从响应文件的有效性和完整性对采购文件的响应程度进行审查，以确定是否对采购文件的实质性要求做出响应。', '详细描述了磋商和评审的流程、标准及响应文件的澄清要求。', 'high', 0, NULL, 5, '[{\"Label\":\"\\u7B26\\u5408\\u6027\\u5BA1\\u67E5\",\"Value\":\"\\u5BA1\\u67E5\\u54CD\\u5E94\\u6587\\u4EF6\\u7684\\u6709\\u6548\\u6027\\u548C\\u5B8C\\u6574\\u6027\",\"FullWidth\":false},{\"Label\":\"\\u5B9E\\u8D28\\u6027\\u8981\\u6C42\",\"Value\":\"\\u786E\\u5B9A\\u662F\\u5426\\u6EE1\\u8DB3\\u5B9E\\u8D28\\u6027\\u8981\\u6C42\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (321, 1, 298, '响应无效情形', '二级目录', '22.2如发现下列情况之一的，其响应将被认定为响应无效：（1）未按照采购文件规定要求签署、盖章的；（2）未满足采购文件中技术条款的实质性要求；（3）与其他响应人串通响应，或者与采购人串通响应；', '列举了导致响应无效的具体情形，包括文件签署、技术条款、串通响应等。', 'high', 1, NULL, 6, '[{\"Label\":\"\\u7B7E\\u7F72\\u76D6\\u7AE0\",\"Value\":\"\\u672A\\u6309\\u89C4\\u5B9A\\u7B7E\\u7F72\\u76D6\\u7AE0\",\"FullWidth\":false},{\"Label\":\"\\u6280\\u672F\\u6761\\u6B3E\",\"Value\":\"\\u672A\\u6EE1\\u8DB3\\u5B9E\\u8D28\\u6027\\u6280\\u672F\\u6761\\u6B3E\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (322, 1, 298, '合同签订与履行', '二级目录', '30.1成交人应当自发出成交通知书之日起30日内，与采购人签订合同。31.1成交人在收到成交通知书后在签订合同前按照采购人确定的数额及方式缴纳项目履约保证金（数额不得超过政府采购合同金额10%）。', '规定了合同签订的时间、依据及履约保证金的要求。', 'medium', 0, NULL, 7, '[{\"Label\":\"\\u7B7E\\u8BA2\\u65F6\\u95F4\",\"Value\":\"\\u6210\\u4EA4\\u901A\\u77E5\\u4E66\\u53D1\\u51FA\\u540E30\\u65E5\\u5185\",\"FullWidth\":false},{\"Label\":\"\\u5C65\\u7EA6\\u4FDD\\u8BC1\\u91D1\",\"Value\":\"\\u4E0D\\u8D85\\u8FC7\\u5408\\u540C\\u91D1\\u989D10%\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (323, 1, 300, '商务符合性审查表', '二级目录', '商务符合性审查表用于审查响应人是否符合商务要求，确保响应文件的完整性和有效性。', '审查响应人是否符合商务要求，确保响应文件的完整性和有效性。', 'medium', 1, NULL, 0, '[]');
INSERT INTO `sales_bid_chapter` VALUES (324, 1, 300, '技术符合性审查表', '二级目录', '技术符合性审查表用于审查响应人是否符合技术要求，确保技术方案的可行性和合规性。', '审查响应人是否符合技术要求，确保技术方案的可行性和合规性。', 'medium', 1, NULL, 1, '[]');
INSERT INTO `sales_bid_chapter` VALUES (325, 1, 300, '评分细则', '二级目录', '报价20分，技术部分46分（项目实施方案18分、服务方案10分、售后服务方案9分、培训方案9分），商务部分34分（履约经验12分、售后服务响应4分、人员配备8分、企业实力8分、扶持不发达地区和少数民族地区2分）。', '详细规定了报价、技术部分和商务部分的评分标准和权重。', 'high', 0, NULL, 2, '[{\"Label\":\"\\u62A5\\u4EF7\\u6743\\u91CD\",\"Value\":\"20\\u5206\",\"FullWidth\":false},{\"Label\":\"\\u6280\\u672F\\u90E8\\u5206\\u6743\\u91CD\",\"Value\":\"46\\u5206\",\"FullWidth\":false},{\"Label\":\"\\u5546\\u52A1\\u90E8\\u5206\\u6743\\u91CD\",\"Value\":\"34\\u5206\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (326, 1, 300, '价格评审', '二级目录', '以满足招标文件要求且投标价格最低的投标报价为评标基准价，其价格分为满分。其他投标人的价格分统一按照下列公式计算：（评标基准价/投标报价）×0.20×100。', '规定了价格评审的具体方法和基准价计算方式。', 'high', 0, NULL, 3, '[{\"Label\":\"\\u4EF7\\u683C\\u8BC4\\u5BA1\\u516C\\u5F0F\",\"Value\":\"(\\u8BC4\\u6807\\u57FA\\u51C6\\u4EF7/\\u6295\\u6807\\u62A5\\u4EF7)\\u00D70.20\\u00D7100\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (327, 1, 300, '中小企业价格扣除', '二级目录', '根据政府采购法相关规定，对小型和微型企业产品的价格给予10%的价格扣除，用扣除后的价格参与评审，并提供证明材料。', '对小型和微型企业产品的价格给予10%的价格扣除，用扣除后的价格参与评审。', 'medium', 0, NULL, 4, '[{\"Label\":\"\\u4EF7\\u683C\\u6263\\u9664\\u6BD4\\u4F8B\",\"Value\":\"10%\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (328, 1, 300, '技术部分评分细则', '二级目录', '项目实施方 案18分，服务方案10分，售后服务方案9分，培训方案9分。', '详细规定了技术部分的评分标准和内容要求。', 'high', 0, NULL, 5, '[{\"Label\":\"\\u9879\\u76EE\\u5B9E\\u65BD\\u65B9 \\u6848\",\"Value\":\"18\\u5206\",\"FullWidth\":false},{\"Label\":\"\\u670D\\u52A1\\u65B9\\u6848\",\"Value\":\"10\\u5206\",\"FullWidth\":false},{\"Label\":\"\\u552E\\u540E\\u670D\\u52A1\\u65B9\\u6848\",\"Value\":\"9\\u5206\",\"FullWidth\":false},{\"Label\":\"\\u57F9\\u8BAD\\u65B9\\u6848\",\"Value\":\"9\\u5206\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (329, 1, 300, '商务部分评分细则', '二级目录', '履约经验12分，售后服务响应4分，人员配备8分，企业实力8分，扶持不发达地区和少数民族地区2分。', '详细规定了商务部分的评分标准和内容要求。', 'high', 0, NULL, 6, '[{\"Label\":\"\\u5C65\\u7EA6\\u7ECF\\u9A8C\",\"Value\":\"12\\u5206\",\"FullWidth\":false},{\"Label\":\"\\u552E\\u540E\\u670D\\u52A1\\u54CD\\u5E94\",\"Value\":\"4\\u5206\",\"FullWidth\":false},{\"Label\":\"\\u4EBA\\u5458\\u914D\\u5907\",\"Value\":\"8\\u5206\",\"FullWidth\":false},{\"Label\":\"\\u4F01\\u4E1A\\u5B9E\\u529B\",\"Value\":\"8\\u5206\",\"FullWidth\":false},{\"Label\":\"\\u6276\\u6301\\u4E0D\\u53D1\\u8FBE\\u5730\\u533A\\u548C\\u5C11\\u6570\\u6C11\\u65CF\\u5730\\u533A\",\"Value\":\"2\\u5206\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (330, 1, 301, '1.3.5 进口产品限制', '二级目录', '若响应人须知资料表中未写明允许采购进口产品，如响应人所投产品为进口产品，其响应将被认定为响应无效。', '明确禁止使用未在响应人须知资料表中列明的进口产品，否则响应无效。', 'high', 1, NULL, 0, '[{\"Label\":\"\\u8FDB\\u53E3\\u4EA7\\u54C1\\u9650\\u5236\",\"Value\":\"\\u672A\\u5217\\u660E\\u7684\\u8FDB\\u53E3\\u4EA7\\u54C1\\u54CD\\u5E94\\u65E0\\u6548\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (331, 1, 301, '1.3.6 中小企业采购限制', '二级目录', '若响应人须知资料表中写明专门面向中小企业采购的，如响应人为非中小企业且所投产品为非中小企业产品，其响应将被认定为响应无效。', '专门面向中小企业采购的项目，非中小企业响应无效。', 'high', 1, NULL, 1, '[{\"Label\":\"\\u4E2D\\u5C0F\\u4F01\\u4E1A\\u9650\\u5236\",\"Value\":\"\\u975E\\u4E2D\\u5C0F\\u4F01\\u4E1A\\u54CD\\u5E94\\u65E0\\u6548\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (332, 1, 301, '1.5 关联关系限制', '二级目录', '单位负责人为同一人或者存在直接控股、管理关系的不同供应商，其相关响应将被认定为响应无效。', '单位负责人为同一人或存在直接控股、管理关系的不同供应商，其响应无效。', 'high', 1, NULL, 2, '[{\"Label\":\"\\u5173\\u8054\\u5173\\u7CFB\\u9650\\u5236\",\"Value\":\"\\u5B58\\u5728\\u5173\\u8054\\u5173\\u7CFB\\u7684\\u54CD\\u5E94\\u65E0\\u6548\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (333, 1, 301, '1.6 服务限制', '二级目录', '为本项目提供过整体设计、规范编制或者项目管理、监理、检测等服务的供应商，不得再参加本项目上述服务以外的其他采购活动。否则其响应将被认定为响应无效。', '为本项目提供过整体设计、规范编制等服务的供应商，不得参加其他采购活动。', 'high', 1, NULL, 3, '[{\"Label\":\"\\u670D\\u52A1\\u9650\\u5236\",\"Value\":\"\\u63D0\\u4F9B\\u8FC7\\u670D\\u52A1\\u7684\\u4F9B\\u5E94\\u5546\\u4E0D\\u5F97\\u53C2\\u52A0\\u5176\\u4ED6\\u91C7\\u8D2D\\u6D3B\\u52A8\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (334, 1, 301, '1.7 贿赂行为', '二级目录', '响应人在响应过程中不得向采购人提供、给予任何有价值的物品，影响其正常决策行为。一经发现，其将被认定为响应无效。', '响应人不得向采购人提供任何有价值的物品，否则响应无效。', 'high', 1, NULL, 4, '[{\"Label\":\"\\u8D3F\\u8D42\\u884C\\u4E3A\",\"Value\":\"\\u63D0\\u4F9B\\u6709\\u4EF7\\u503C\\u7269\\u54C1\\u7684\\u54CD\\u5E94\\u65E0\\u6548\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (335, 1, 301, '2.3 报价超限', '二级目录', '响应人报价超过采购文件规定的预算金额或者分项、分包最高限价的，其响应将被认定为响应无效。', '响应人报价超过预算金额或分项最高限价的，响应无效。', 'high', 1, NULL, 5, '[{\"Label\":\"\\u62A5\\u4EF7\\u8D85\\u9650\",\"Value\":\"\\u8D85\\u8FC7\\u9884\\u7B97\\u6216\\u6700\\u9AD8\\u9650\\u4EF7\\u7684\\u54CD\\u5E94\\u65E0\\u6548\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (336, 1, 301, '22.2 响应无效情形', '二级目录', '如发现下列情况之一的，其响应将被认定为响应无效：（1）未按照采购文件规定要求签署、盖章的；（2）未满足采购文件中技术条款的实质性要求；（3）与其他响应人串通响应，或者与采购人串通响应；...（17）明显不符合技术规格、技术标准的要求。', '列举了多种可能导致响应无效的情形，包括技术条款不满足、串通响应等。', 'high', 1, NULL, 6, '[{\"Label\":\"\\u54CD\\u5E94\\u65E0\\u6548\\u60C5\\u5F62\",\"Value\":\"17\\u79CD\\u60C5\\u5F62\\u5BFC\\u81F4\\u54CD\\u5E94\\u65E0\\u6548\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (337, 1, 301, '1.6.1 违约责任', '二级目录', '除不可抗力外，如果乙方没有按照本合同约定的期限、地点和方式交付货物（服务、工程），那么甲方可要求乙方支付违约金，违约金按每迟延交付货物（服务、工程）一日的应交付而未交付货物（服务、工程）价格的 %计算，最高限额为本合同总价的 %；', '延迟交付货物（服务、工程）的违约金计算及最高限额。', 'medium', 0, NULL, 7, '[{\"Label\":\"\\u8FDD\\u7EA6\\u91D1\\u8BA1\\u7B97\",\"Value\":\"\\u6309\\u65E5\\u8BA1\\u7B97\\uFF0C\\u6700\\u9AD8\\u9650\\u989D\\u4E3A\\u5408\\u540C\\u603B\\u4EF7\\u7684%\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (338, 1, 301, '1.6.3 合同解除', '二级目录', '除不可抗力外，任何一方未能履行本合同约定的其他主要义务，经催告后在合理期限内仍未履行的，或者任何一方有其他违约行为致使不能实现合同目的的，或者任何一方有腐败行为或者欺诈行为的，对方当事人可以书面通知违约方解除本合同；', '任何一方未能履行主要义务或存在腐败、欺诈行为，对方可解除合同。', 'high', 0, NULL, 8, '[{\"Label\":\"\\u5408\\u540C\\u89E3\\u9664\",\"Value\":\"\\u8150\\u8D25\\u3001\\u6B3A\\u8BC8\\u884C\\u4E3A\\u53EF\\u89E3\\u9664\\u5408\\u540C\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_chapter` VALUES (339, 1, 301, '2.21 履约保证金', '二级目录', '采购文件要求乙方提交履约保证金的，乙方应按合同专用条款约定的方式，以支票、汇票、本票或者金融机构、担保机构出具的保函等非现金形式，提交不超过合同价10%的履约保证金；...如果乙方不履行合同，履约保证金不予退还；如果乙方未能按合同约定全面履行义务，那么甲方有权从履约保证金中取得补偿或赔偿，同时不影响甲方要求乙方承担合同约定的超过履约保证金的违约责任的权利。', '履约保证金的提交、退还及违约处理。', 'medium', 0, NULL, 9, '[{\"Label\":\"\\u5C65\\u7EA6\\u4FDD\\u8BC1\\u91D1\",\"Value\":\"\\u4E0D\\u8D85\\u8FC7\\u5408\\u540C\\u4EF710%\\uFF0C\\u8FDD\\u7EA6\\u4E0D\\u9000\\u8FD8\",\"FullWidth\":false}]');
INSERT INTO `sales_bid_project` VALUES ('3f3020f260e441d08822256f306f345e', 'BID-2024-004', '智慧校园一卡通系统', '某知名大学', '西南区 - 四川省', '系统集成', '¥ 3,200,000', '2024-08-10 09:00:00.000000', '赵六', '进行中', '建设覆盖全校的智能一卡通系统，实现身份识别、消费支付、图书借阅、门禁管理等一卡通用功能，支持手机NFC及二维码。', '2026-01-09 20:45:42.532730', '2026-01-09 20:45:42.532730');
INSERT INTO `sales_bid_project` VALUES ('8337e373f6364b5e8ad6152ec127af14', 'BID-2024-002', '某集团ERP升级改造', '某大型制造业集团', '华北区 - 北京市', '企业管理软件', '¥ 8,500,000', '2024-06-15 14:00:00.000000', '李四', '已中标', '针对集团现有ERP系统性能瓶颈及功能缺失进行全面升级，涵盖供应链、生产制造、财务核算等核心模块，要求支持云端部署及移动端应用。', '2026-01-09 20:45:42.532730', '2026-01-09 20:45:42.532730');
INSERT INTO `sales_bid_project` VALUES ('9305f522094f45d0859ed30d70ef2340', 'BID-2024-003', '政务云平台采购', '某省政府办公厅', '华南区 - 广东省', '云计算/基础设施', '¥ 12,000,000', '2024-07-20 10:00:00.000000', '王五', '未中标', '采购一批高性能服务器、存储设备及网络安全设备，构建省流政务云平台基础设施，并提供为期3年的运维服务。', '2026-01-09 20:45:42.532730', '2026-01-09 20:45:42.532730');
INSERT INTO `sales_bid_project` VALUES ('da8d8a289d5b4a43863d275ab5b6de7b', 'BID-2024-005', '医院HIS系统维护服务', '某三甲医院', '华中区 - 湖北省', '运维服务', '¥ 1,500,000', '2024-05-25 15:00:00.000000', '孙七', '流标', '提供为期一年的HIS系统驻场运维服务，保障医院核心业务系统7x24小时稳定运行，负责故障排查、系统优化及数据备份。', '2026-01-09 20:45:42.532730', '2026-01-09 20:45:42.532730');
